const fatherhoodChapter:Chapter={id:'fatherhood',period:'≈2018—NOW',kicker:'FATHERHOOD · OVERLAPS SERVICE · PRESENCE',title:L('בתוך שנות השירות נהייתי אבא — והילדות חזרה אליי מהצד השני.','During the service years I became a father — and childhood returned from the other side.','Во время службы я стал отцом — и детство вернулось с другой стороны.'),body:L('האבהות התחילה עוד בתוך שנות המשטרה, לא אחרי StartOn. היא החזירה אותי לשאלות של נוכחות, נטישה, גבולות וטכנולוגיה. ב־2023 חלק מהשאלות האלה יצאו בפומבי דרך הטקסט על “אבא מושלם” והכתיבה על ילדים בעולם דיגיטלי. אני משאיר את הפרק אישי בלי להפוך את הילדים לחומר גלם ויזואלי.','Fatherhood began during the police years, not after StartOn. It brought me back to questions of presence, abandonment, boundaries and technology. In 2023 some of those questions became public through the “perfect father” story and writing about children in a digital world. I keep the chapter personal without turning the children into visual material.','Отцовство началось ещё в годы службы в полиции, а не после StartOn. Оно вернуло меня к вопросам присутствия, оставления, границ и технологий. В 2023 году часть этих вопросов стала публичной через историю об «идеальном отце» и тексты о детях в цифровом мире. Я сохраняю эту главу личной, не превращая детей в визуальный материал.'),tags:['FATHERHOOD','PRESENCE','DIGITAL PARENTING','RESPONSIBILITY'],image:'https://static.zman.co.il/www/uploads/terms-images/writer/20815-profilepic-medium.jpeg',visual:'PUBLIC AUTHOR PORTRAIT · ZMAN ISRAEL · PUBLISHER-LINKED · NO CHILD IMAGERY',links:[{label:L('אבא מושלם — LinkedIn','Perfect father — LinkedIn','Идеальный отец — LinkedIn'),href:'https://www.linkedin.com/posts/vepretski_%D7%9B%D7%A9%D7%94%D7%94%D7%95%D7%A8%D7%99%D7%9D-%D7%A9%D7%9C%D7%99-%D7%94%D7%AA%D7%92%D7%A8%D7%A9%D7%95-%D7%90%D7%91%D7%90-%D7%A9%D7%9C%D7%99-%D7%97%D7%AA%D7%9D-%D7%93%D7%99%D7%9C-activity-7032741993654988800-IRtv?trk=public_profile_like_view'},{label:L('לבן שלי אין טיקטוק!','My son does not have TikTok!','У моего сына нет TikTok!'),href:'https://www.zman.co.il/350569/'}]};
const creationChapter:Chapter={id:'culture',canonicalId:'life-music-2025',period:'2020—NOW',kicker:'CREATION · MUSIC · PARALLEL THREAD',title:L('במקביל לשירות ולאבהות, נפתח גם קו יצירתי שלא נסגר.','Alongside service and fatherhood, a creative thread opened and never really closed.','Параллельно службе и отцовству открылся творческий поток, который так и не закрылся.'),body:L('מ־2020 והלאה מוזיקה, וידאו, הומור ושיתופי פעולה רצים במקביל לחיים הציבוריים — מ״מת על אקסל״ ועד BIZZI ותכני #7YA. זה לא פרק שהתחיל רק ב־2025; 2025 הוא רגע בתוך קו יצירה ארוך יותר.','From 2020 onward, music, video, humour and collaborations run in parallel with public life — from “Met al Excel” through BIZZI and #7YA content. This did not begin in 2025; 2025 is one moment inside a longer creative line.','С 2020 года музыка, видео, юмор и коллаборации идут параллельно общественной жизни — от «Met al Excel» до BIZZI и контента #7YA. Это началось не в 2025 году; 2025-й — лишь один момент более длинной творческой линии.'),tags:['MUSIC','VIDEO','CREATION','PARALLEL'],image:'https://i.ytimg.com/vi/2HGMUN2jDwQ/hqdefault.jpg',visual:'OFFICIAL YOUTUBE MUSIC VIDEO · 2020',links:[{label:L('מת על אקסל','Met al Excel','Met al Excel'),href:'https://www.youtube.com/watch?v=2HGMUN2jDwQ'},{label:L('BIZZI','BIZZI','BIZZI'),href:'https://www.youtube.com/watch?v=jRjZjpqAgEw'}]};const identityChapter:Chapter={id:'break',canonicalId:'identity-longform-2024',period:'2023—2024',kicker:'OCT 7 · IDENTITY · LONGFORM',title:L('אחרי 7 באוקטובר, גם האופן שבו דיברתי השתנה.','After October 7, the way I spoke changed too.','После 7 октября изменился и мой способ говорить.'),body:L('מאוקטובר 2023 והלאה, שיחות ארוכות ופודקאסטים קיבלו משקל אחר: פחות צורך להעלות עוד סאונדבייט, יותר צורך להחזיק כאב, ביטחון, ביקורת, אחריות וזהות באותה שיחה.','From October 2023 onward, long conversations and podcasts carried a different weight: less need for another soundbite, more need to hold pain, security, criticism, responsibility and identity in the same conversation.','С октября 2023 года длинные разговоры и подкасты получили другой вес: меньше потребности в очередном коротком тезисе, больше — удерживать боль, безопасность, критику, ответственность и идентичность в одном разговоре.'),tags:['OCT 7','IDENTITY','LONGFORM'],image:driveThumb('1M1LCw-9IqVLcf0dkF-2MaJhaHmPkqvvw'),visual:'PUBLIC INSTAGRAM PHOTO · PUBLIC LIFE / POLITICAL WORK · 2024',links:[{label:L('שיחת עומק','Longform conversation','Длинный разговор'),href:'https://www.youtube.com/watch?v=3h-oEuW8GJI'}]};const studiesChapter:Chapter={id:'studies',canonicalId:'hebrew-university-criminology-2018-2020',period:'2018—2020',kicker:'STUDIES · CRIMINOLOGY · HEBREW UNIVERSITY',title:L('בתוך שנות השירות רציתי להבין מקצועית את מה שכבר ראיתי בשטח.','During the service years I wanted a professional language for what I was already seeing in the field.','Во время службы мне понадобился профессиональный язык для того, что я уже видел в поле.'),body:narrativeByCanonicalId['hebrew-university-criminology-2018-2020'],tags:['CRIMINOLOGY','HEBREW UNIVERSITY','STUDIES'],visual:'ACADEMIC CHAPTER · SOURCE-LINKED',links:[{label:L('הפרופיל המקצועי','Professional profile','Профессиональный профиль'),href:'https://www.linkedin.com/in/vepretski/'}]};const startOnChapter:Chapter={id:'starton',period:'2022',kicker:'STARTON · JESSE COHEN · BUILD',title:L('החזרה קיבלה צורה: StartOn.','The return took physical form: StartOn.','Возвращение получило форму: StartOn.'),body:L('החזרה לג׳סי כהן לא נשארה סיפור. StartOn הפכה אותה למודל פעולה: טכנולוגיה, יצירה, מרחב שייכות ומבוגרים שמופיעים לפני המשבר — לא אחריו.','The return to Jesse Cohen did not remain a story. StartOn turned it into an operating model: technology, creation, belonging and adults who arrive before crisis, not after it.','Возвращение в Джесси Коэн не осталось историей. StartOn превратил его в модель действия: технологии, творчество, принадлежность и взрослые, которые приходят до кризиса, а не после него.'),tags:['STARTON','JESSE COHEN','YOUTH','OPPORTUNITY'],image:'https://pic1.yitweb.co.il/cdn-cgi/image/f%3Dauto%2Cw%3D1200%2Cq%3D85/picserver/mynet/crop_images/2022/05/11/r1F0NeKU9/r1F0NeKU9_0_0_640_360_0_large.jpg',visual:'PUBLIC PRESS PHOTO · MYNET · 13.05.2022',links:[{label:L('StartOn','StartOn','StartOn'),href:'https://starton.org.il/'},{label:L('ראיון חדשות 13','News 13 interview','Интервью News 13'),href:'https://prod.13tv.co.il/item/news/haolam-haboker/season-01/clips/u0uoy-903061791/?pid=44'}]};const insertStudies=(chapters:Chapter[])=>{if(chapters.some(chapter=>chapter.id==='studies'||chapter.canonicalId==='hebrew-university-criminology-2018-2020'))return chapters;const next=[...chapters];const serviceIndex=next.findIndex(chapter=>chapter.id==='service');next.splice(serviceIndex>=0?serviceIndex+1:1,0,studiesChapter);return next};const insertStartOn=(chapters:Chapter[])=>{if(chapters.some(chapter=>chapter.id==='starton'))return chapters;const next=[...chapters];const returnIndex=next.findIndex(chapter=>chapter.id==='return');next.splice(returnIndex>=0?returnIndex+1:Math.min(4,next.length),0,startOnChapter);return next};const insertFatherhood=(chapters:Chapter[])=>{if(chapters.some(chapter=>chapter.id==='fatherhood'))return chapters;const next=[...chapters];const startOnIndex=next.findIndex(chapter=>chapter.id==='starton');const returnIndex=next.findIndex(chapter=>chapter.id==='return');const voiceIndex=next.findIndex(chapter=>chapter.id==='voice');next.splice(startOnIndex>=0?startOnIndex+1:returnIndex>=0?returnIndex+1:voiceIndex>=0?voiceIndex:Math.min(5,next.length),0,fatherhoodChapter);return next};const spineCanonicalIds=new Set(['origin-belonging-1990s','camp-henry-horner-recovered-film','service-field-2011-2021','hebrew-university-criminology-2018-2020','starton-return-2022','fatherhood-viral-2023-02-20','public-voice-2023','identity-longform-2024','life-music-2025','research-collective-imagination-2026','7ya-now-snapshot-2026']);const spineRank:Record<string,number>={origin:0,'camp-henry-horner-recovered-film':1,service:2,studies:3,fatherhood:4,culture:5,return:6,starton:7,voice:8,break:9,research:10,now:11};const spineKey=(chapter:Chapter)=>chapter.canonicalId==='hebrew-university-criminology-2018-2020'?'studies':chapter.id;const orderSpine=(chapters:Chapter[])=>[...chapters].sort((a,b)=>(spineRank[spineKey(a)]??99)-(spineRank[spineKey(b)]??99));
