const metricValue=(value:string|number)=>typeof value==='number'?value.toLocaleString('en-US'):value;const metricDate=(date:string)=>{const [y,m,d]=date.split('-');return d&&m&&y?`${d}.${m}.${y}`:date};const metricLabel=(metric:CorpusMetric)=>metric.metricType==='publication-records'?'PUBLICATION RECORDS':`${(metric.platform||metric.metricType).toUpperCase()} · ${metricDate(metric.snapshotDate)}`;
const trustLabel=(state:string,locale:Locale)=>{const labels:Record<string,Local>={verified:L('מאומת','Verified','Проверено'),supported:L('נתמך','Supported','Подтверждено'),inferred:L('מוסק','Inferred','Вывод'),['owner-reported']:L('דיווח עצמי','Self-reported','Самоописание'),unresolved:L('דורש אימות','Requires verification','Требует проверки'),quarantined:L('בהסגר','Quarantined','Карантин'),contradicted:L('במחלוקת','Contradicted','Противоречие')};return(labels[state]||L(state,state,state))[locale]};const trustClass=(state:string)=>state.toLowerCase().replace(/[^a-z0-9]+/g,'-');
const ui={he:{eyebrow:'12 פרקים · סיפור אחד / 1990 → עכשיו',title:'כרונולוגיה ברורה — בלי למחוק את החפיפות.',body:'ילדות ועלייה → Camp Henry Horner והיצירה הקבוצתית המוקדמת → שירות → לימודי קרימינולוגיה ואבהות בתוך שנות השירות → יצירה ומוזיקה מ־2020 → חזרה לג׳סי כהן ו־StartOn ב־2022 → קול ציבורי → זהות אחרי 7 באוקטובר → מחקר → עכשיו. כששני פרקים קורים במקביל, האתר אומר את זה במקום להעמיד פנים שהם קרו בטור.',source:'למקור',metrics:'צילום מצב של גוף התוכן · יוני 2026',note:'ספירת מופעים בפלטפורמות. פרסום צולב עשוי להופיע ביותר מפלטפורמה אחת; הנתונים נשארים מתוארכים.',canonLive:'CANON LIVE · פרקי הציר נטענו מהקאנון הציבורי הפעיל',canonFallback:'FALLBACK · הקאנון החי לא נטען; מוצגים פרקי גיבוי עם קישורי מקור בלבד'},en:{eyebrow:'12 CHAPTERS · ONE STORY / 1990 → NOW',title:'A clear chronology without erasing the overlaps.',body:'Childhood and immigration → Camp Henry Horner and early group creation → service → criminology studies and fatherhood during the service years → music and creation from 2020 → return to Jesse Cohen and StartOn in 2022 → public voice → identity after October 7 → research → now. When chapters overlap, the site says so instead of forcing a false sequence.',source:'Source',metrics:'Content-body snapshot · June 2026',note:'Platform-instance counts. Cross-posted material may appear on more than one platform; figures remain dated.',canonLive:'CANON LIVE · timeline chapters loaded from the active public canon',canonFallback:'FALLBACK · live canon unavailable; source-linked backup chapters are shown'},ru:{eyebrow:'12 ГЛАВ · ОДНА ИСТОРИЯ / 1990 → СЕЙЧАС',title:'Понятная хронология — без стирания пересечений.',body:'Детство и переезд → Camp Henry Horner и раннее групповое творчество → служба → криминология и отцовство в годы службы → музыка и творчество с 2020 года → возвращение в Джесси Коэн и StartOn в 2022 году → публичный голос → идентичность после 7 октября → исследования → сейчас. Когда главы пересекаются, сайт показывает это, а не выстраивает ложную очередь.',source:'Источник',metrics:'Снимок массива контента · июнь 2026',note:'Считаются размещения на платформах. Кросс-пост может учитываться более одного раза; показатели остаются датированными.',canonLive:'CANON LIVE · главы загружены из активного публичного канона',canonFallback:'FALLBACK · живой канон недоступен; показаны резервные главы со ссылками на источники'}} as const;
const fail=(event:SyntheticEvent<HTMLImageElement>)=>{const image=event.currentTarget;if(image.dataset.fallback)return;image.dataset.fallback='1';const parent=image.parentElement;parent?.classList.add('pc-media-failed');image.remove()};
export default function PersonalChronology(){const {locale}=useLocale();const c=ui[locale];const local=(value:Local)=>value[locale];const [corpus,setCorpus]=useState<CorpusResponse|null>(null);const [corpusState,setCorpusState]=useState<'loading'|'backend'|'fallback'>('loading');useEffect(()=>{let live=true;fetchCanonicalCorpus(100).then(data=>{if(!live)return;setCorpus(data);setCorpusState('backend')}).catch(()=>{if(live)setCorpusState('fallback')});return()=>{live=false}},[]);const activeChapters=useMemo(()=>{const chapters=corpusState==='backend'&&corpus?corpus.items.filter(event=>spineCanonicalIds.has(event.id)&&!embeddedMediaCanonicalIds.has(event.id)).map(chapterFromEvent):fallbackChapters.filter(chapter=>chapter.id!=='twenties').map(chapter=>chapter.id==='culture'?creationChapter:chapter.id==='break'?identityChapter:chapter);return orderSpine(insertFatherhood(insertStartOn(insertStudies(chapters))))},[corpus,corpusState]);return <section className='personal-chronology' id='life-chronology' aria-labelledby='personal-chronology-title'><div className='pc-shell'><header className='pc-head'><div><p>{c.eyebrow}</p><h2 id='personal-chronology-title'>{c.title}</h2></div><p>{c.body}</p></header><div className={'pc-corpus-status '+(corpusState==='backend'?'backend':corpusState==='fallback'?'fallback':'')} role='status'><ShieldCheck/><span>{corpusState==='backend'?c.canonLive:corpusState==='fallback'?c.canonFallback:locale==='he'?'מחבר את הקאנון החי…':locale==='ru'?'Подключаю живой канон…':'Connecting live canon…'}</span></div><nav className='pc-years' aria-label={c.eyebrow}>{activeChapters.map((chapter,index)=><a href={'#life-'+chapter.id} key={chapter.id}><small>{String(index+1).padStart(2,'0')}</small><b>{chapter.period}</b><span>{local(chapter.title)}</span></a>)}</nav><div className='pc-flow'>{activeChapters.map((chapter,index)=><article className={'pc-chapter pc-'+chapter.id+(chapter.imageFit==='contain'?' pc-contain':'')} id={'life-'+chapter.id} data-canonical-id={chapter.canonicalId} key={chapter.canonicalId||chapter.id}><div className='pc-media'>{chapter.id==='fatherhood'?<div className='pc-fatherhood-artifact' role='img' aria-label={fatherhoodArtifact[locale].quote}><div className='pc-fatherhood-mark'><span dir='ltr'>FATHERHOOD / AUTHORED SOURCE</span><b dir='ltr'>2022—2023</b></div><blockquote>{fatherhoodArtifact[locale].quote}</blockquote><div className='pc-fatherhood-path'><small>{fatherhoodArtifact[locale].path}</small><strong dir='ltr'>{fatherhoodArtifact[locale].source}</strong></div></div>:chapter.image?<><img src={chapter.image} alt={local(chapter.title)} loading={index<2?'eager':'lazy'} decoding='async' referrerPolicy='no-referrer' onError={fail}/></>:<div className='pc-source-object' role='img' aria-label={local(chapter.title)}><Sparkles/><small>{chapter.period}</small><strong>{local(chapter.title)}</strong><b>IGOR VEPRETSKI</b></div>}</div><div className='pc-copy'><div className='pc-meta'><span>{chapter.period}</span><b>{chapter.kicker}</b></div>{chapter.verificationState&&<div className={'pc-trust pc-trust-'+trustClass(chapter.verificationState)} data-verification-state={chapter.verificationState}><ShieldCheck/>{chapter.evidenceGrade&&<strong>{chapter.evidenceGrade}</strong>}<span>{trustLabel(chapter.verificationState,locale)}</span>{chapter.verificationNote&&<small>{chapter.verificationNote}</small>}</div>}<h3>{local(chapter.title)}</h3><p>{local(chapter.body)}</p><div className='pc-tags'>{chapter.tags.map(tag=><span key={tag}>{tag}</span>)}</div><nav className='pc-links'>{chapter.links.map(link=><a href={link.href} target={link.href.startsWith('http')?'_blank':undefined} rel={link.href.startsWith('http')?'noreferrer':undefined} key={link.href}>{local(link.label)}{link.href.startsWith('http')?<ExternalLink/>:<ArrowUpLeft/>}</a>)}</nav>{chapter.id==='return'&&<a className='pc-return-bridge' href='#life-starton'><small dir='ltr'>{returnBridge[locale].label}</small><strong>{returnBridge[locale].title}</strong><span>{returnBridge[locale].body}</span><b>↓</b></a>}{chapter.id==='service'&&<div className='pc-service-ledger' aria-label={locale==='he'?'ציר השירות המאומת':locale==='ru'?'Подтверждённая хронология службы':'Verified service chronology'}>{serviceLedger.map(item=><div key={item.no}><span>{item.no}</span><strong dir='ltr'>{item.label}</strong><time dir='ltr'>{item.period}</time><small>{locale==='he'?'רשומה מאומתת':locale==='ru'?'Подтверждённая запись':'Verified record'}</small></div>)}</div>}{chapter.id!=='return'&&<MediaEchoCluster chapterId={chapter.id}/>} {knowledgeLensByChapterId.get(chapter.id)&&<KnowledgeLensCard lens={knowledgeLensByChapterId.get(chapter.id)!}/>} {chapter.metrics&&<div className='pc-metrics' aria-label={c.metrics}>{(chapter.metricsData?.length?chapter.metricsData:fallbackMetrics).map(metric=><div key={metric.metricType}><b>{metricValue(metric.value)}</b><span>{metricLabel(metric)}</span></div>)}<small><ShieldCheck/>{c.note}</small></div>}</div></article>)}</div><footer className='pc-footer'><div><Newspaper/><span>PRESS · POSTS · MEDIA</span></div><div><Music2/><span>MUSIC · CULTURE</span></div><div><BookOpen/><span>ACADEMIA · RESEARCH</span></div><a href={pageHref('media',locale)}>{locale==='he'?'לכל התוכן':locale==='ru'?'Весь контент':'All content'}<ArrowUpLeft/></a></footer></div></section>}
